"""Alternate the driver with and without the counting global allocator."""
import json, os, statistics, subprocess, sys
root = "/home/dhilipsiva/projects/dhilipsiva/botwork"
inputs = f"{root}/target/performance/campaign-n3ydbdda/inputs"
drivers = {"counting": sys.argv[1], "plain": sys.argv[2]}
work = {"loop": 1_000_000, "calls": 100_000}
times = {(w, d): [] for w in work for d in drivers}
print("load before", os.getloadavg())
for pair in range(8):
    for name, units in work.items():
        order = list(drivers) if pair % 2 == 0 else list(reversed(drivers))
        for driver in order:
            out = subprocess.run([drivers[driver], name, f"{inputs}/{name}.botwork", str(units), "--wait-ms", "10"],
                                 capture_output=True, text=True, check=True).stdout
            times[(name, driver)].append(json.loads(out)["elapsed_ns"] / 1e6)
print("load after", os.getloadavg())
for name in work:
    counting, plain = (statistics.median(times[(name, d)]) for d in ("counting", "plain"))
    print(f"{name}: median counting {counting:.1f} ms, plain {plain:.1f} ms, ratio {counting / plain:.3f}")
print(json.dumps({f"{w}/{d}": v for (w, d), v in times.items()}))
